using LiveCG.Core;
using SkiaSharp;
internal static class V12Checks
{
    public static async Task Run(string folder,Action<bool,string> check)
    {
        Repro(check);var dir=Path.Combine(folder,"v12");Directory.CreateDirectory(dir);
        var red=new SKColor(125,20,32);var other=new SKColor(145,26,39);using var texture=new SKBitmap(240,100);for(var y=0;y<100;y++)for(var x=0;x<240;x++)texture.SetPixel(x,y,(x/5+y/5)%2==0?red:other);
        using(var c=new SKCanvas(texture))using(var p=new SKPaint{Color=SKColors.White,Style=SKPaintStyle.Stroke,StrokeWidth=4,IsAntialias=true}){c.DrawCircle(40,45,24,p);c.DrawRect(90,20,38,48,p);p.StrokeWidth=1;c.DrawLine(170.5f,15,170.5f,85,p);}
        var settings=new TextSeparationSettings{RangeMode=true,BackgroundColors=["#7D1420","#911A27"],ColorTolerance=20};using(var matte=TextSeparation.Extract(texture,red,SKColors.White,settings))
        {
            var support=true;var removed=true;for(var y=0;y<100;y++)for(var x=0;x<240;x++){var c=texture.GetPixel(x,y);if(c!=red&&c!=other&&matte.Mask.Alpha[y*240+x]==0)support=false;if((c==red||c==other)&&matte.Mask.Alpha[y*240+x]!=0)removed=false;}
            check(support,"range separation retains every original ink support pixel on a two-tone pattern");check(removed,"multiple background samples clear both texture colors including closed counters");check(Enumerable.Range(20,60).All(y=>matte.Mask.Alpha[y*240+170]>0),"text range mode preserves one-pixel strokes without contour erosion");
        }
        var copy=settings.Copy();copy.BackgroundColors.Clear();check(settings.BackgroundColors.Count==2,"range settings do not alias snapshot background colors");
        var maskData=new byte[1024*512];for(var i=0;i<maskData.Length;i++)maskData[i]=(byte)(i%256);var buffer=new MaskBuffer(1024,512,maskData);var fastTimer=System.Diagnostics.Stopwatch.StartNew();using var fastMask=buffer.Bitmap();fastTimer.Stop();var slowTimer=System.Diagnostics.Stopwatch.StartNew();using var reference=new SKBitmap(1024,512);for(var y=0;y<512;y++)for(var x=0;x<1024;x++)reference.SetPixel(x,y,SKColors.White.WithAlpha(maskData[y*1024+x]));slowTimer.Stop();check(fastMask.Bytes.SequenceEqual(reference.Bytes),"bulk mask rendering preserves every premultiplied alpha byte");Console.WriteLine($"PERF mask bitmap fast={fastTimer.Elapsed.TotalMilliseconds:0.00}ms reference={slowTimer.Elapsed.TotalMilliseconds:0.00}ms");check(fastTimer.ElapsedTicks<Math.Max(slowTimer.ElapsedTicks*2,System.Diagnostics.Stopwatch.Frequency/20),"bulk mask conversion avoids the per-pixel graphics-call cost");
        check(new VideoOptions().Output==OutputKind.Browser,"new work defaults to OBS browser without changing persisted enum values");
        var appended=TimelineRules.Append(new(),new(){Kind=EffectKind.TravelRoute},7,30);check(appended.Route is not null,"appending a travel effect initializes a valid route before timing validation");
        using var map=new SKBitmap(640,400);map.Erase(new(17,48,78));using(var c=new SKCanvas(map))using(var p=new SKPaint{Color=new(35,92,121),IsAntialias=true}){c.DrawRoundRect(new(30,30,610,370),55,55,p);p.Color=new(26,65,94);c.DrawOval(new(120,90,540,300),p);}
        var mapPath=Path.Combine(dir,"여행 지도.png");SourceImage.SavePng(map,mapPath);var route=new TravelRoute{Arrival=false,Points=[new(){X=.1,Y=.7,Name="출발",Stop=1},new(){X=.5,Y=.2,Name="경유",Move=2,Stop=1,Icon=TravelIcon.Car},new(){X=.9,Y=.7,Name="도착",Move=2,Stop=1}]};var geometry=RouteRenderer.Geometry(route);
        check(route.Duration==7,"route duration sums movement and per-waypoint stops");check(geometry.Sample(route,.5).Stopped&&geometry.Sample(route,.5).X==.1,"departure dwell holds the first point");check(Math.Abs(geometry.Sample(route,2).X-.3)<.0001&&!geometry.Sample(route,2).Stopped,"movement advances by arc length between stops");check(geometry.Sample(route,3.5).Stopped&&geometry.Sample(route,3.5).X==.5,"waypoint dwell holds its exact location");check(geometry.Sample(route,4.5).Icon==TravelIcon.Car,"waypoint transport override controls the next leg");check(geometry.Sample(route,50).X==.9&&geometry.Sample(route,50).Stopped,"arrival retains the final position after route completion");
        var cloned=route.Copy();cloned.Points[0].Stop=0;check(route.Points[0].Stop==1,"route copies preserve independent waypoint timings");route.Curved=true;check(Math.Abs(RouteRenderer.Geometry(route).Segments[0].Y[32]-.45)<1e-8,"smooth mode alone preserves straight route geometry");route.Curved=false;
        foreach(var kind in Enum.GetValues<TravelIcon>()){using var icon=RouteRenderer.Icon(route,kind);check(icon.Width<=512&&icon.Bytes.Where((_,i)=>i%4==3).Any(v=>v>0),kind+" travel icon has visible transparent artwork");}
        var overlay=new EffectRegion{Name="여행",Bounds=new(0,0,1,1),OverlayOnly=true,ContentOnly=false,Background=BackgroundMode.KeepOriginal,Clips=[new(){Duration=7,Route=route,Options=new(){Kind=EffectKind.TravelRoute}}]};var job=new ImageJob{SourcePath=mapPath,Width=640,Height=400,Regions=[overlay]};
        using(var scene=new EffectScene(map)){using var before=scene.Render(job.Regions,new(),0);using var moved=scene.Render(job.Regions,new(),2);check(before.GetPixel(0,0)==map.GetPixel(0,0)&&moved.GetPixel(0,0)==map.GetPixel(0,0),"travel overlay leaves the source map untouched outside its graphics");check(!before.Bytes.SequenceEqual(moved.Bytes),"travel icon and visited trail visibly advance");}
        var file=Path.Combine(dir,"route.json");DocumentStore.Save(file,new ProjectDocument{Jobs=[job]});var restored=DocumentStore.Load<ProjectDocument>(file);check(restored.Jobs[0].Regions[0].Clips[0].Route!.Points[1].Icon==TravelIcon.Car,"route project JSON preserves points, timing and transport changes");
        var asset=new EffectAsset{Name="여행 에셋",Clips=[overlay.Clips[0].Copy()]};DocumentStore.Save(Path.Combine(dir,"route-asset.json"),asset);check(DocumentStore.Load<EffectAsset>(Path.Combine(dir,"route-asset.json")).Clips[0].Route!.Duration==7,"travel routes round trip as reusable user assets");
        var hidden=job.Snapshot();hidden.Regions[0].Enabled=false;using(var scene=new EffectScene(map)){using var frame=scene.Render(hidden.Regions,new(),.5);check(frame.Bytes.SequenceEqual(map.Bytes),"hiding a travel overlay never erases or recolors the underlying map");}await ExportFixture(hidden,"route-hidden.obs",[.5]);
        var parent=new EffectRegion{Name="지도 그룹",Bounds=new(0,0,1,1),Role=RegionRole.Group,Background=BackgroundMode.KeepOriginal};var child=overlay.Copy();child.ParentId=parent.Id;child.Role=RegionRole.EffectArea;child.Bounds=new(.15,.1,.7,.8);child.Masks=[new(){Bounds=new(.4,.1,.1,.1),Operation=MaskOperation.Subtract}];var grouped=job.Snapshot();grouped.Regions=[child,parent];using(var scene=new EffectScene(map)){using var frame=scene.Render(grouped.Regions,new(),2);check(frame.GetPixel(0,0)==map.GetPixel(0,0),"grouped route overlays preserve parent map pixels outside their graphics");}await ExportFixture(grouped,"route-GroupMask.obs",[2,3.5,7]);
        async Task ExportFixture(ImageJob fixture,string name,double[] times){var target=Path.Combine(folder,name);await new BrowserExporter().ExportAsync(fixture,new(){Fps=30,EndHold=0},target,true,null,CancellationToken.None);Directory.CreateDirectory(Path.Combine(target,"expected"));using var scene=new EffectScene(map);foreach(var t in times){using var frame=scene.Render(fixture.Regions,new(){Fps=30},t);SourceImage.SavePng(frame,Path.Combine(target,"expected",t.ToString("0.00",System.Globalization.CultureInfo.InvariantCulture)+".png"));}}
        foreach(var style in Enum.GetValues<RouteLineStyle>())
        {
            var r=route.Copy();r.Arrival=style==RouteLineStyle.Solid;r.LineStyle=style;r.Curved=style is RouteLineStyle.Dotted or RouteLineStyle.Arrows;r.Animate=style==RouteLineStyle.Dotted;if(style==RouteLineStyle.Dotted){r.Color="#8058F5A6";r.Opacity=.65;}if(style==RouteLineStyle.Arrows){using var custom=new SKBitmap(120,60);custom.Erase(SKColors.Transparent);using(var c=new SKCanvas(custom))using(var p=new SKPaint{Color=SKColors.Orange})c.DrawRoundRect(new(10,10,110,50),8,8,p);r.CustomPng=ObjectExtractor.EncodeBitmap(custom);r.Icon=TravelIcon.Custom;}
            var region=overlay.Copy();region.Clips[0].Route=r;var j=job.Snapshot();j.Regions=[region];var target=Path.Combine(folder,"route-"+style+".obs");await new BrowserExporter().ExportAsync(j,new(){Fps=30,EndHold=0},target,true,null,CancellationToken.None);Directory.CreateDirectory(Path.Combine(target,"expected"));using var scene=new EffectScene(map);foreach(var t in new[]{.5,2,3.5,5,7d}){using var frame=scene.Render(j.Regions,new(){Fps=30},t);SourceImage.SavePng(frame,Path.Combine(target,"expected",t.ToString("0.00",System.Globalization.CultureInfo.InvariantCulture)+".png"));}check(File.ReadAllText(Path.Combine(target,"data.js")).Contains("segments"),style+" route exports shared measured path and icon assets");
        }
        var cropRegion=new EffectRegion{Bounds=new(0,0,1,1),ContentOnly=true,SeparationTarget=SeparationTarget.Text,TextInkColor="#FFFFFF",TextSettings=settings,Background=BackgroundMode.Solid,BackgroundColor="#7D1420",Clips=[new(){Duration=1,Options=new(){Kind=EffectKind.Zoom}}]};using(var scene=new EffectScene(texture)){using var first=scene.Render([cropRegion],new(),.2);var count=TextSeparation.Calculations;var timer=System.Diagnostics.Stopwatch.StartNew();for(var i=0;i<20;i++){using var frame=scene.Render([cropRegion],new(),.2);}check(TextSeparation.Calculations==count,"repeated selection-style redraws reuse text extraction rather than recalculating pixels");check(timer.ElapsedMilliseconds<5000,"cached text redraw stays responsive on a representative crop");}
    }
    public static void Repro(Action<bool,string> check)
    {
        using var white=new SKBitmap(260,80);white.Erase(SKColors.White);using(var c=new SKCanvas(white))using(var p=new SKPaint{Color=new(130,64,45)}){for(var i=0;i<5;i++)c.DrawRect(10+i*46,8,34,64,p);c.DrawRect(10,38,218,2,p);}
        var cells=DigitCells.Find(white,SKColors.White);check(cells.Count==5,"joined dark price digits on a white background split into five rolling cells");
        using var dark=new SKBitmap(260,80);dark.Erase(new(130,64,45));using(var c=new SKCanvas(dark))using(var p=new SKPaint{Color=SKColors.White})for(var i=0;i<5;i++)c.DrawRect(10+i*46,8,34,64,p);
        check(DigitCells.Find(dark,new(130,64,45)).Count==5,"separated white price digits on a dark background remain five cells");
        var userPath=Environment.GetEnvironmentVariable("LIVECG_TEST_PRICE_SCREENSHOT");if(File.Exists(userPath)){using var provided=SKBitmap.Decode(userPath);using var crop=new SKBitmap();provided.ExtractSubset(crop,new(262,88,600,198));check(DigitCells.Find(crop,DigitCells.Background(crop,SKColors.White)).Count==5,"user-provided white-background price crop detects all five digit cells");}
    }
}
